import dlabrd = require( './index' );


// TESTS //

// The function returns void...
{
	const A = new Float64Array( 6 );
	const D = new Float64Array( 1 );
	const E = new Float64Array( 1 );
	const TAUQ = new Float64Array( 1 );
	const TAUP = new Float64Array( 1 );
	const X = new Float64Array( 3 );
	const Y = new Float64Array( 2 );

	dlabrd( 'column-major', 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectType void
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 6 );
	const D = new Float64Array( 1 );
	const E = new Float64Array( 1 );
	const TAUQ = new Float64Array( 1 );
	const TAUP = new Float64Array( 1 );
	const X = new Float64Array( 3 );
	const Y = new Float64Array( 2 );

	dlabrd( 5, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( true, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( false, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( null, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( void 0, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( [], 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( {}, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
	dlabrd( ( x: number ): number => x, 3, 2, 1, A, 3, D, E, TAUQ, TAUP, X, 3, Y, 2 ); // $ExpectError
}

